// Parse die Kernfragen aus der AI-Antwort
const aiResponse = $input.first().json;
let coreQuestions = [];

try {
  // Versuche JSON aus der Antwort zu extrahieren
  const jsonMatch = aiResponse.text.match(/\[\s*\{[\s\S]*\}\s*\]/g);
  if (jsonMatch) {
    coreQuestions = JSON.parse(jsonMatch[0]);
  } else if (typeof aiResponse.text === 'object') {
    coreQuestions = aiResponse.text;
  }
} catch (e) {
  // Fallback: Erstelle eine einfache Frage
  coreQuestions = [
    {id: 1, question: aiResponse.text, priority: 'hoch'}
  ];
}

// Kontext für spätere Nodes beibehalten
const context = {
  topic: $('Variablen setzen').first().json.topic,
  context: $('Variablen setzen').first().json.context,
  email: $('Variablen setzen').first().json.email,
  humanInLoop: $('Variablen setzen').first().json.humanInLoop,
  analysisId: $('Variablen setzen').first().json.analysisId,
  coreQuestions: coreQuestions
};

// Gib jede Kernfrage als separates Item aus für den Loop
return coreQuestions.map((q, index) => ({
  json: {
    ...context,
    currentQuestion: q,
    questionIndex: index + 1,
    totalQuestions: coreQuestions.length
  }
}));

// Extrahiere und formatiere Suchergebnisse
const searchResults = $input.first().json;
const previousData = $('Loop - Jede Kernfrage').first().json;

let formattedResults = [];

if (searchResults.results && Array.isArray(searchResults.results)) {
  formattedResults = searchResults.results.slice(0, 10).map((r, i) => ({
    position: i + 1,
    title: r.title || 'Kein Titel',
    url: r.url || '',
    content: r.content || r.snippet || 'Keine Beschreibung',
    source: r.engine || 'unknown'
  }));
}

const searchSummary = formattedResults.map(r => 
  `[${r.position}] ${r.title}\n   URL: ${r.url}\n   ${r.content}`
).join('\n\n');

return [{
  json: {
    ...previousData,
    searchResults: formattedResults,
    searchSummary: searchSummary || 'Keine Suchergebnisse gefunden.'
  }
}];

// Speichere die Analyse für diese Kernfrage
const input = $input.first().json;
const analysis = input.text || input.response || JSON.stringify(input);

const previousData = $('Suchergebnisse formatieren').first().json;

return [{
  json: {
    ...previousData,
    questionAnalysis: analysis
  }
}];

// Sammle alle Analysen aus dem Loop
const items = $input.all();

const allAnalyses = items.map(item => ({
  questionIndex: item.json.questionIndex,
  question: item.json.currentQuestion.question,
  priority: item.json.currentQuestion.priority,
  analysis: item.json.questionAnalysis,
  searchResults: item.json.searchResults
}));

// Sortiere nach Index
allAnalyses.sort((a, b) => a.questionIndex - b.questionIndex);

// Formatiere für den finalen AI-Call
const analysisDocument = allAnalyses.map(a => 
  `### Kernfrage ${a.questionIndex}: ${a.question}\n\n${a.analysis}`
).join('\n\n---\n\n');

return [{
  json: {
    topic: items[0].json.topic,
    context: items[0].json.context,
    email: items[0].json.email,
    humanInLoop: items[0].json.humanInLoop,
    analysisId: items[0].json.analysisId,
    coreQuestions: items[0].json.coreQuestions,
    allAnalyses: allAnalyses,
    analysisDocument: analysisDocument
  }
}];

const input = $input.first().json;
const selfCritique = input.text || input.response || JSON.stringify(input);
const previousData = $('Alle Analysen zusammenführen').first().json;

return [{
  json: {
    ...previousData,
    selfCritique: selfCritique
  }
}];

const input = $input.first().json;
const synthesis = input.text || input.response || JSON.stringify(input);
const previousData = $('Selbstkritik speichern').first().json;
const now = new Date();

// Erstelle das finale Markdown-Dokument
const markdownDocument = `# Marktanalyse: ${previousData.topic}

**Analyse-ID:** ${previousData.analysisId}  
**Erstellt am:** ${now.toLocaleDateString('de-DE')} um ${now.toLocaleTimeString('de-DE')}  
**Analysiert für:** eggs unimedia GmbH

---

## Unternehmenskontext

${previousData.context}

---

## Schritt 1: Strukturierte Erkundung - Kernfragen

${previousData.coreQuestions.map((q, i) => `${i + 1}. **${q.question}** *(Priorität: ${q.priority})*`).join('\n')}

---

## Schritt 2 & 3: Hypothesen und Evidenzbewertung

${previousData.analysisDocument}

---

## Schritt 4: Selbstkritik

${previousData.selfCritique}

---

## Schritt 5: Synthese

${synthesis}

---

*Diese Analyse wurde automatisiert erstellt. Die Qualität hängt von den verfügbaren Quellen und der Aktualität der Web-Recherche ab.*
`;

return [{
  json: {
    ...previousData,
    synthesis: synthesis,
    markdownDocument: markdownDocument,
    filename: `Marktanalyse_${previousData.topic.replace(/[^a-zA-Z0-9]/g, '_')}_${previousData.analysisId}.md`
  }
}];
